window.MOTIF_CATALOG_CHUNKS[68]={"cards":[{"id":"MEJE-KW-006916","row_version":1,"title":"비공식 지도자","original":"De Facto Leader","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"임명이나 선출을 거치지 않았지만 집단의 신뢰와 행동을 이끌어 사실상 지도자로 인정받는 인물이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006916/index.html"},{"id":"MEJE-KW-006917","row_version":1,"title":"어린이용 순화 공포","original":"Defanged Horrors","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"어린 독자나 관객에게 공포의 즐거움은 주되 자극의 강도와 표현을 조절한 공포물이다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-006917/index.html"},{"id":"MEJE-KW-006918","row_version":1,"title":"기본 설정에 몰리는 선택","original":"Default Setting Syndrome","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 여러 선택지를 제공해도 많은 이용자가 기본으로 지정된 항목을 그대로 사용해 특정 경험이 널리 반복된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006918/index.html"},{"id":"MEJE-KW-006919","row_version":1,"title":"기본적으로 선한 선택","original":"Default to Good","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"자기 이익을 먼저 챙기는 듯한 인물도 결정적인 순간에는 남을 돕는 쪽을 택하며 본래의 선의를 드러낸다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006919/index.html"},{"id":"MEJE-KW-006920","row_version":1,"title":"데프콘 단계의 오용","original":"DEFCON-5","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"경계 단계의 숫자가 높을수록 위험하다고 잘못 표현해 실제 순서와 반대로 쓰는 군사 용어 오류다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006920/index.html"},{"id":"MEJE-KW-006921","row_version":2,"title":"패배로 시작하는 과거사","original":"Defeat as Backstory","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"중요한 과거의 패배가 인물의 성격과 목표를 만들고 현재의 선택에 오래 영향을 미친다. 과거의 패배가 인물을 형성했다면 무패의 상대를 꺾기은 현재의 강자를 새롭게 정의한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006921/index.html"},{"id":"MEJE-KW-006922","row_version":1,"title":"노출을 이용한 전투 종료","original":"Defeat by Modesty","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"대결 중 옷이 벗겨질 위기에 놓인 인물이 몸을 가리거나 물러나느라 싸움을 이어 가지 못한다. 신체 노출을 웃음거리로 삼는 연출에는 맥락을 살필 필요가 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006922/index.html"},{"id":"MEJE-KW-006923","row_version":1,"title":"변신으로 제압하기","original":"Defeat by Transformation","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"상대의 형태를 바꾸어 위협을 없애거나 행동 능력을 제한함으로써 싸움을 끝낸다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006923/index.html"},{"id":"MEJE-KW-006924","row_version":1,"title":"패배할 때마다 하는 대사","original":"Defeat Catchphrase","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"반복적으로 패배하는 인물이 매번 같은 문장을 외쳐 실패 자체를 알아볼 수 있는 장면 규칙으로 만든다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006924/index.html"},{"id":"MEJE-KW-006925","row_version":1,"title":"패자를 전리품으로 만들기","original":"Defeated and Trophified","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"승자가 패배한 인물을 살아 있는 수집품처럼 전시하거나 소유해 권력과 잔혹성을 과시한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006925/index.html"},{"id":"MEJE-KW-006926","row_version":1,"title":"쓰러지면 폭발하는 적","original":"Defeat Equals Explosion","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임이나 영상에서 적이 패배와 동시에 폭발해 처치 사실을 즉각적이고 강렬하게 알린다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006926/index.html"},{"id":"MEJE-KW-006927","row_version":2,"title":"반칙 상대를 정정당당하게 이기기","original":"Defeating the Cheating Opponent","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"부정행위를 하는 상대를 알면서도 같은 수단을 쓰지 않고 공정한 승리로 맞선다. 공정한 승리를 거둔 뒤 패한 쪽이 승자를 인정하는 패배 뒤 인정으로 이어질 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006927/index.html"},{"id":"MEJE-KW-006928","row_version":2,"title":"무패의 상대를 꺾기","original":"Defeating the Undefeatable","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"누구도 이기지 못한다고 여긴 강자가 처음으로 패배해 기존의 힘의 질서가 바뀐다. 처음 패배한 강자가 상대를 존중하게 되는 패배 뒤 인정을 촉발할 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006928/index.html"},{"id":"MEJE-KW-006929","row_version":2,"title":"패배 뒤 우정","original":"Defeat Means Friendship","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"대결에서 진 인물이 상대를 적으로만 보지 않게 되고 이후 동료나 친구가 된다. 패배를 계기로 생긴 패배 뒤 인정이 더 깊어지면 적대가 우정으로 바뀔 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006929/index.html"},{"id":"MEJE-KW-006930","row_version":1,"title":"패배 뒤 허드렛일","original":"Defeat Means Menial Labor","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"몰락한 적이 이전 권위와 어울리지 않는 잡무를 하며 패배의 결과를 드러낸다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006930/index.html"},{"id":"MEJE-KW-006931","row_version":2,"title":"이기면 조작 가능","original":"Defeat Means Playable","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 상대를 쓰러뜨린 뒤 그 인물이 플레이어가 선택할 수 있는 캐릭터로 열린다. 일반 적으로 격하된 보스과 달리 패배한 상대가 플레이어의 선택지로 들어오며 지위가 바뀐다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006931/index.html"},{"id":"MEJE-KW-006932","row_version":1,"title":"패배 뒤 인정","original":"Defeat Means Respect","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"상대를 얕보던 인물이 패한 뒤 그 실력을 인정하고 존중하게 된다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006932/index.html"},{"id":"MEJE-KW-006933","row_version":1,"title":"사랑 때문에 진영 이탈","original":"Defecting for Love","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"기존 소속의 명령과 사랑하는 사람 사이에서 갈등하던 인물이 관계를 택해 진영을 옮긴다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006933/index.html"},{"id":"MEJE-KW-006934","row_version":1,"title":"결함을 지닌 명탐정","original":"Defective Detective","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"수사 능력은 뛰어나지만 사생활이나 대인관계에서 반복되는 문제를 안고 있는 탐정이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006934/index.html"},{"id":"MEJE-KW-006935","row_version":1,"title":"냉전 시대의 망명자","original":"Defector from Commie Land","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"냉전 배경 이야기에서 동구권 또는 공산 진영을 떠나 서방으로 가려는 인물이다. 시대적 관점이 인물의 묘사에 영향을 준다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006935/index.html"},{"id":"MEJE-KW-006936","row_version":1,"title":"소속의 타락을 떠나는 인물","original":"Defector from Decadence","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"기존 조직의 비윤리적 행위에 환멸을 느껴 신념과 소속을 바꾸는 인물이다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006936/index.html"},{"id":"MEJE-KW-006937","row_version":1,"title":"낙원을 떠나는 인물","original":"Defector from Paradise","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"안전하고 풍요로운 장소에서도 충족되지 않는 욕구 때문에 스스로 떠나 새로운 삶을 찾는다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006937/index.html"},{"id":"MEJE-KW-006938","row_version":1,"title":"위협에 반응하는 능력","original":"Defence Mechanism Superpower","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"초자연적 능력이 평소에는 발동하지 않다가 인물이 위험에 처하면 저절로 드러난다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-006938/index.html"},{"id":"MEJE-KW-006939","row_version":1,"title":"방어 명령","original":"Defend Command","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 공격을 포기하거나 늦추는 대신 받는 피해를 줄이는 행동 선택이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006939/index.html"},{"id":"MEJE-KW-006940","row_version":1,"title":"심판받는 영혼의 변호자","original":"Defender of the Judged Soul","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"죽은 자의 심판에서 다른 존재가 영혼을 대신 변호하거나 구하려 나서며 사후 세계의 갈등에 개입한다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006940/index.html"},{"id":"MEJE-KW-006941","row_version":1,"title":"동류에게서 타인을 지키기","original":"Defends Against Their Own Kind","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"어떤 특성을 공유한 인물이 같은 부류의 위협으로부터 다른 집단을 보호한다. 공통 정체성이 곧 같은 가치관을 뜻하지 않음을 보여 준다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006941/index.html"},{"id":"MEJE-KW-006942","row_version":1,"title":"이별하며 물건 내던지기","original":"Defenestrate and Berate","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"관계가 끝난 뒤 상대의 소지품을 집 밖으로 던져 결별 의사와 분노를 눈에 보이게 한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006942/index.html"},{"id":"MEJE-KW-006943","row_version":1,"title":"무장 없는 수송 유닛","original":"Defenseless Transports","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"전략 게임에서 병력을 옮기는 유닛이 공격 수단이 없어 호위가 필요한 대상으로 기능한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006943/index.html"},{"id":"MEJE-KW-006944","row_version":1,"title":"쓸 수 없는 방어 수단","original":"Defensive Failure","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"방어할 수단을 쥔 인물이 결정적인 순간에 사용하지 못해 위협 앞에서 무력해진다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006944/index.html"},{"id":"MEJE-KW-006945","row_version":1,"title":"약한 척하는 방어 진형","original":"Defensive Feint Trap","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"방어하는 쪽이 후퇴하거나 취약해 보이는 모습을 보여 상대를 끌어들인 뒤 전세를 뒤집는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006945/index.html"},{"id":"MEJE-KW-006946","row_version":1,"title":"눈치 없는 반문","original":"Defensive \"What?\"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"부적절하거나 놀라운 말을 한 인물이 주변의 시선에 당황해 '왜?'라고 되묻는다. 자신의 발언이 만든 반응을 이해하지 못한 태도가 장면의 핵심이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006946/index.html"},{"id":"MEJE-KW-006947","row_version":2,"title":"굴복하지 않는 포로","original":"Defiant Captive","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"붙잡힌 뒤에도 요구에 순순히 따르지 않고 말과 태도로 저항하는 인물이다. 끝까지 굽히지 않기은 포로 상태의 지속적인 저항이며, 끝까지 굽히지 않기는 마지막 대면에서 두드러진다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006947/index.html"},{"id":"MEJE-KW-006948","row_version":2,"title":"돌멩이로 하는 저항","original":"Defiant Stone Throw","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"압도적인 지배자 앞에서 약한 인물이 작은 돌을 던지며 복종 거부의 의지를 드러낸다. 끝까지 굽히지 않기의 의지를 작은 물건 하나로 시각화한 장면이다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-006948/index.html"},{"id":"MEJE-KW-006949","row_version":1,"title":"나체로 하는 항의","original":"Defiant Strip","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 스스로 옷을 벗어 강요나 권위에 맞서며 몸에 대한 주도권을 주장한다. 장면의 핵심은 노출보다 항의의 의사다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006949/index.html"},{"id":"MEJE-KW-006950","row_version":1,"title":"끝까지 굽히지 않기","original":"Defiant to the End","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"패배하거나 붙잡힌 인물이 마지막 순간까지 상대의 권위를 인정하지 않고 자기 뜻을 고수한다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006950/index.html"},{"id":"MEJE-KW-006951","row_version":1,"title":"허구 상품의 현실화","original":"Defictionalization","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품 속에만 있던 상품이나 소품을 현실의 실제 물건으로 만들어 판매하거나 전시한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006951/index.html"},{"id":"MEJE-KW-006952","row_version":1,"title":"클리셰를 의식적으로 거부하기","original":"Defied Trope","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"이야기 속 인물이 익숙한 전개가 일어나려는 징후를 알아차리고 의도적으로 다른 선택을 한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006952/index.html"},{"id":"MEJE-KW-006953","row_version":2,"title":"영원한 오염이라는 낙인","original":"Defiled Forever","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"성폭력 피해나 혼인 밖의 성경험 때문에 인물의 가치가 영원히 훼손되었다고 보는 편견이다. 이야기는 그 낙인이 당사자에게 가하는 사회적 폭력을 드러낼 수 있다. 성경험을 이유로 인격 전체를 부정하는 낙인은 비인간화의 한 형태다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-006953/index.html"},{"id":"MEJE-KW-006954","row_version":1,"title":"분명 감기일 뿐이라는 부정","original":"Definitely Just a Cold","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"뚜렷한 이상 징후를 겪는 인물이 상황을 가벼운 병으로 여기며 더 큰 문제를 외면한다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006954/index.html"},{"id":"MEJE-KW-006955","row_version":1,"title":"편향 방어막","original":"Deflector Shields","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"우주선이나 시설 둘레에 형성되는 에너지 장벽이 외부의 공격이나 충돌을 막는다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006955/index.html"},{"id":"MEJE-KW-006956","row_version":1,"title":"전장의 안개 걷어내기","original":"Defog of War","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 감춰진 지형과 적 정보를 기술이나 능력으로 드러내 전술적 판단을 가능하게 한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006956/index.html"},{"id":"MEJE-KW-006957","row_version":1,"title":"차가운 인물의 마음 열기","original":"Defrosting Ice Queen","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"감정을 드러내지 않던 인물이 가까운 관계를 통해 점차 경계를 풀고 애정을 표현한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006957/index.html"},{"id":"MEJE-KW-006958","row_version":1,"title":"서비스 종료 온라인 게임","original":"Defunct Online Video Games","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"서버 운영에 의존하던 온라인 게임이 서비스 종료 뒤 정상적인 플레이가 어려워지는 상태다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006958/index.html"},{"id":"MEJE-KW-006959","row_version":2,"title":"무기로 길러진 아이 구하기","original":"Defusing the Tyke-Bomb","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"싸움의 도구로 자란 아이를 한 사람으로 대하며 폭력적 역할에서 벗어날 길을 열어 준다. 무기로만 취급받던 아이를 한 인격으로 대하는 변화는 비인간화에 맞선다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006959/index.html"},{"id":"MEJE-KW-006960","row_version":1,"title":"검열에 맞서는 발표","original":"Defying the Censors","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"창작자가 검열을 예상하면서도 표현을 숨기지 않고 공개해 제도와 직접 충돌한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006960/index.html"},{"id":"MEJE-KW-006961","row_version":2,"title":"일반 적으로 격하된 보스","original":"Degraded Boss","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"한때 강력한 보스였던 적이 게임 후반에는 흔한 적으로 다시 등장해 플레이어의 성장을 체감하게 한다. 패배 이후 적의 지위가 바뀌는 게임 관습이지만 이기면 조작 가능에서는 플레이 가능 캐릭터가 된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006961/index.html"},{"id":"MEJE-KW-006962","row_version":1,"title":"비인간화","original":"Dehumanization","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"한 사람이나 집단을 온전한 인간으로 인정하지 않는 관점과 묘사다. 이야기 속에서 차별과 폭력을 정당화하는 언어로 작동할 수 있다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-006962/index.html"},{"id":"MEJE-KW-006963","row_version":1,"title":"사람 취급하지 않는 모욕","original":"Dehumanizing Insult","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"상대를 열등한 존재나 물건에 빗대어 인간으로서의 존엄을 깎아내리는 말이다. 차별과 지배 관계를 언어로 드러낸다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006963/index.html"},{"id":"MEJE-KW-006964","row_version":1,"title":"신격의 정체성 혼동","original":"Deity Identity Confusion","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"전승이나 작품에서 본래 별개였던 신들이 같은 존재로 여겨지거나 한 신의 성격이 다른 신에게 합쳐진다. 세대와 문화가 바뀌며 신화의 계보가 재해석된다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006964/index.html"},{"id":"MEJE-KW-006965","row_version":2,"title":"필멸자에서 비롯된 신","original":"Deity of Human Origin","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"한때 인간이나 다른 필멸 종족이었던 존재가 신격으로 오르거나 필멸자들의 행위로 실제 신이 만들어지는 설정. 단순히 신 같은 힘을 보이는 것과 구분된다. 사람의 믿음이 신격을 실재하게 만드는 경우는 필멸자가 만들어 낸 신이라는 더 구체적인 설정이 된다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-006965/index.html"},{"id":"MEJE-KW-006966","row_version":1,"title":"필멸자가 만들어 낸 신","original":"Deity of Mortal Creation","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"필멸자의 집단적 믿음·감정에서 신이 생겨나거나 마법과 기술로 의도적으로 신을 만드는 세계관 규칙. 신은 숭배와 별개로 존재할 수도 있다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-006966/index.html"},{"id":"MEJE-KW-006967","row_version":2,"title":"뒤늦게 나타나는 타격 결과","original":"Delayed Causality","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"공격이 닿은 뒤 짧은 정적이 흐르고 나서야 피해가 화면에 드러난다. 물리적 시간보다 장면의 리듬을 우선하는 연출이다. 원인과 결과 사이에 정적을 놓는 연출이라는 점에서 뒤늦게 터지는 폭발과 나란히 볼 수 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006967/index.html"},{"id":"MEJE-KW-006968","row_version":1,"title":"뒤늦게 밝혀진 진단","original":"Delayed Diagnosis","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물의 질환이나 장애가 처음에는 분명히 알려지지 않다가 여러 차례의 확인 끝에 진단된다. 불확실한 기간이 생활과 관계에 부담을 남긴다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006968/index.html"},{"id":"MEJE-KW-006969","row_version":1,"title":"뒤늦게 터지는 폭발","original":"Delayed Explosion","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"폭발을 일으킨 사건과 실제 폭발 사이에 극적인 지연이 놓인다. 잠깐의 침묵이 뒤따를 충격을 키운다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006969/index.html"},{"id":"MEJE-KW-006970","row_version":1,"title":"늦게 찾아온 가족의 수용","original":"Delayed Family Acceptance","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"가족이 어떤 인물의 정체성이나 선택을 처음에는 거부하다가 시간이 흐른 뒤 받아들인다. 화해가 늦어진 만큼 상처와 변화가 함께 남는다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006970/index.html"},{"id":"MEJE-KW-006971","row_version":1,"title":"늦게 맡는 지도자의 자리","original":"Delayed Leadership Ascendance","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"능력과 경험이 있어도 지휘를 피하던 인물이 여러 사건 뒤에야 지도자 역할을 받아들인다. 리더십이 타고난 자격보다 선택과 책임으로 완성된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006971/index.html"},{"id":"MEJE-KW-006972","row_version":1,"title":"성장을 미루면 얻는 이득","original":"Delayed Level Benefits","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 즉시 레벨을 올리기보다 특정 기술이나 조건을 먼저 갖추어 나중의 성장을 유리하게 만든다. 빠른 보상과 장기적 이득 사이에 선택이 생긴다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006972/index.html"},{"id":"MEJE-KW-006973","row_version":2,"title":"뒤늦게 등장하는 화자","original":"Delayed Narrator Introduction","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"이야기를 들려주던 목소리의 주인이 본편 중간에 인물로 등장한다. 익명의 해설로 여겼던 말을 특정 인물의 경험으로 다시 읽게 한다. 이야기를 전하던 목소리의 정체가 바뀌면 관객이 사건을 새롭게 해석할 수 있으며 모든 일을 환상으로 돌리는 해석 같은 수용 방식도 생긴다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006973/index.html"},{"id":"MEJE-KW-006974","row_version":2,"title":"뒤늦게 깨닫는 위기","original":"Delayed \"Oh, Crap!\"","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"들었을 때는 대수롭지 않게 넘긴 말을 나중에 다시 떠올리고서야 위험을 깨닫는다. 정보가 전달된 시점과 의미를 이해한 시점이 어긋난다. 반응이 늦게 나온다는 공통점이 있지만 늦게 오는 반응은 위기 이외의 상황에도 쓰인다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006974/index.html"},{"id":"MEJE-KW-006975","row_version":1,"title":"늦게 오는 반응","original":"Delayed Reaction","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"놀랄 만한 말을 듣거나 사건을 겪은 인물이 평소처럼 행동하다가 잠시 후 갑자기 반응한다. 주변과 관객이 먼저 알아챈 의미가 웃음이나 불안을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006975/index.html"},{"id":"MEJE-KW-006976","row_version":1,"title":"본편보다 먼저 나온 연계 상품","original":"Delayed Release Tie-In","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품의 공개가 연기되었는데 예정 일정에 맞춰 준비한 상품은 먼저 출시된다. 제작과 유통의 일정이 어긋난 결과가 관객에게 노출된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006976/index.html"},{"id":"MEJE-KW-006977","row_version":2,"title":"늦게 퍼지는 시간 변경의 여파","original":"Delayed Ripple Effect","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"과거를 바꾼 뒤에도 현재의 세계는 즉시 변하지 않고 변화가 서서히 따라온다. 주인공에게 원래의 미래를 되찾을 잠깐의 시간이 주어진다. 변화가 뒤늦게 나타나는 동안 마지막 순간까지 미뤄지는 성공의 긴장을 만들 수 있다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-006977/index.html"},{"id":"MEJE-KW-006978","row_version":1,"title":"한 박자 늦은 안전 장치","original":"Delayed Safety Feature","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"위기가 끝난 뒤에야 에어백이나 낙하산 같은 장치가 작동한다. 늦은 안전 조치가 안도감을 다시 소동으로 뒤집는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006978/index.html"},{"id":"MEJE-KW-006979","row_version":2,"title":"마지막 순간까지 미뤄지는 성공","original":"Delayed Until the Final Countdown","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"제한 시간이 있는 임무가 여러 차질을 겪다가 종료 직전에야 해결된다. 성공 가능성을 끝까지 열어 둔 채 긴장을 높인다. 누군가가 시간을 벌어 주는 시간을 벌기 위한 저지전을 함께 배치하면 마지막 순간의 성공이 가능해진다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006979/index.html"},{"id":"MEJE-KW-006980","row_version":1,"title":"시간을 벌기 위한 저지전","original":"Delaying Action","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"열세에 있는 집단이 승리보다 아군의 탈출이나 지원 도착까지 시간을 버는 데 목표를 둔다. 버티는 시간이 전투의 성과가 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006980/index.html"},{"id":"MEJE-KW-006981","row_version":1,"title":"구조를 미루는 구원자","original":"Delaying the Rescue","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"구할 능력이 있는 인물이 다른 목표나 사정 때문에 위기에 빠진 사람을 당장 구하지 않는다. 구원자의 우선순위가 관계와 도덕적 갈등을 만든다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006981/index.html"},{"id":"MEJE-KW-006982","row_version":2,"title":"끝없이 떠넘기는 지시","original":"Delegation Relay","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"윗사람이 맡긴 일을 다음 사람이 다시 아랫사람에게 넘기면서 지시가 줄줄이 이어진다. 책임과 노동이 위계의 맨 아래로 몰린다. 위계에서 주목과 책임을 피하려는 행동은 일부러 실력을 낮춰 보이기과 이어질 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006982/index.html"},{"id":"MEJE-KW-006983","row_version":2,"title":"편집에서 사라진 배역","original":"Deleted Role","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"배우가 촬영까지 마친 배역이 최종 편집에서 통째로 빠진다. 제작 과정에서 존재했던 인물이 공개된 작품에서는 보이지 않는다. 한 인물의 장면이 모두 빠지면 삭제된 장면을 넘어 배역 자체가 사라진다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006983/index.html"},{"id":"MEJE-KW-006984","row_version":1,"title":"삭제된 장면","original":"Deleted Scene","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"제작하거나 촬영했지만 최종 공개판에는 들어가지 않은 장면이다. 추가판이나 부가 자료에서 다시 공개될 수 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006984/index.html"},{"id":"MEJE-KW-006985","row_version":2,"title":"저장 데이터 삭제로 벌하기","original":"Deletion as Punishment","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임이 특정 행동을 한 플레이어에게 저장한 진행을 지우는 방식으로 불이익을 준다. 가상 인물보다 플레이어의 누적 성과가 직접 영향을 받는다. 플레이어의 진행 기록을 건드리는 연출은 의도적으로 오류를 흉내 내는 게임처럼 게임 바깥의 문제로 보이게 만들 수도 있다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006985/index.html"},{"id":"MEJE-KW-006986","row_version":1,"title":"결함도 의도였다고 뒤늦게 주장하기","original":"Deliberate Flaw Retcon","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품의 문제점이 지적된 뒤 제작자가 처음부터 의도한 표현이었다고 해명한다. 실제 제작 의도와 사후 변명을 둘러싼 해석 갈등이 생긴다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006986/index.html"},{"id":"MEJE-KW-006987","row_version":1,"title":"의도적으로 오류를 흉내 내는 게임","original":"Deliberate Game Crash","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임이 실제 장애처럼 보이는 종료 화면이나 재시작을 계획된 연출로 보여 준다. 플레이어가 게임 바깥의 문제인지 이야기 속 사건인지 잠시 헷갈리게 한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006987/index.html"},{"id":"MEJE-KW-006988","row_version":1,"title":"상처를 감수하는 승부수","original":"Deliberate Injury Gambit","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 일부러 불리한 타격을 허용하고 그 대가로 상대를 제압할 기회를 얻는다. 희생을 통한 역전이 결단의 무게를 보여 준다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006988/index.html"},{"id":"MEJE-KW-006989","row_version":2,"title":"거짓임을 알면서 받아들이기","original":"Deliberately Accepting the Lie","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 거짓말임을 눈치채고도 위로, 관계, 체면 같은 이유로 진실인 듯 받아들인다. 믿음의 선택이 사실 판단과 분리된다. 상대의 행동을 알면서도 사랑이라고 믿는 모습은 부모의 사랑을 오해하는 자녀에서 특히 아프게 드러난다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006989/index.html"},{"id":"MEJE-KW-006990","row_version":1,"title":"비교를 위해 세운 나쁜 본보기","original":"Deliberately Bad Example","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"작품이 더 심한 잘못을 하는 인물을 앞세워 주인공의 문제 행동을 상대적으로 온건하게 보이게 한다. 관객의 도덕적 비교를 유도하는 인물 배치다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006990/index.html"},{"id":"MEJE-KW-006991","row_version":1,"title":"귀여움을 연기하는 아이","original":"Deliberately Cute Child","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"아이가 사랑스러운 말투와 표정을 일부러 사용해 어른의 경계를 풀고 원하는 것을 얻는다. 천진함처럼 보이는 태도가 계산된 행동이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006991/index.html"},{"id":"MEJE-KW-006992","row_version":1,"title":"유독 다른 아이템 설명","original":"Deliberately Different Description","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"비슷한 물건의 설명이 일정한 형식을 따르다가 한 아이템만 다른 어조나 내용으로 소개된다. 작은 문장 차이가 숨은 속성이나 비밀을 암시한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006992/index.html"},{"id":"MEJE-KW-006993","row_version":1,"title":"스스로 만든 구출 상황","original":"Deliberately Distressed Damsel","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"위기에 빠진 듯 보이는 인물이 실제로는 그 상황을 의도하거나 기꺼이 받아들인다. 구조 대상이라는 겉모습과 주도적인 목적이 어긋난다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006993/index.html"},{"id":"MEJE-KW-006994","row_version":1,"title":"일부러 앞당긴 출발","original":"Deliberately Jumping the Gun","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"경기나 대결의 정식 시작 전에 한쪽이 의도적으로 먼저 행동해 우위를 잡는다. 공정한 출발이라는 약속을 깨는 선택이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006994/index.html"},{"id":"MEJE-KW-006995","row_version":2,"title":"의도적인 흑백 화면","original":"Deliberately Monochrome","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"색을 쓸 수 있는 작품이 분위기와 주제를 위해 화면을 흑백으로 만든다. 시대적 인상이나 강한 명암 대비를 표현 선택으로 활용한다. 과거 영상의 분위기를 재현할 때 의도적으로 낡은 비디오 화질을 흑백 화면과 결합할 수 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-006995/index.html"},{"id":"MEJE-KW-006996","row_version":1,"title":"일부러 살려 두는 공격","original":"Deliberately Non-Lethal Attack","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"상대를 제압하면서도 죽이지 않도록 공격의 결과를 조절한다. 인물의 윤리나 살아 있는 상대가 필요한 목적이 드러난다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006996/index.html"},{"id":"MEJE-KW-006997","row_version":1,"title":"고통을 감수하며 입는 옷","original":"Deliberately Painful Clothing","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"인물이 신념, 속죄, 능력 획득 등의 이유로 몸에 고통을 주는 옷을 스스로 입는다. 의복이 외형뿐 아니라 선택의 대가를 보여 준다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006997/index.html"},{"id":"MEJE-KW-006998","row_version":2,"title":"초능력 대신 평범한 이동","original":"Deliberate Mundane Traveling","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"빠르게 이동할 특별한 능력이 있는데도 인물이 걷거나 일반 교통수단을 고른다. 능력 사용의 필요와 일상의 편의를 분리해 보여 준다. 가진 능력을 일부러 다 쓰지 않는다는 점에서 일부러 실력을 낮춰 보이기와 맞닿는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006998/index.html"},{"id":"MEJE-KW-006999","row_version":1,"title":"일부러 실력을 낮춰 보이기","original":"Deliberate Under-Performance","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 기대와 책임을 피하거나 정체를 숨기기 위해 실제 능력보다 못한 성적을 낸다. 낮은 평가가 오히려 원하는 자유를 준다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006999/index.html"},{"id":"MEJE-KW-007000","row_version":2,"title":"의도적으로 드러내는 시대의 가치 차이","original":"Deliberate Values Dissonance","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품이 다른 시대나 문화의 가치관을 오늘날 관객에게 불편하게 느껴지더라도 그대로 드러낸다. 인물의 행동을 현대의 기준에 맞춰 순화하지 않아 문화적 거리를 보여 준다. 과거의 정치적 태도를 그대로 재현한 작품은 민주주의를 악으로 그리기이라는 현재의 평가를 받을 수도 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007000/index.html"},{"id":"MEJE-KW-007001","row_version":1,"title":"의도적으로 낡은 비디오 화질","original":"Deliberate VHS Quality","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"새로 만든 영상에 VHS 테이프의 노이즈와 낮은 해상도를 흉내 내 오래된 기록처럼 보이게 한다. 매체의 결함이 의도적인 미학이 된다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-007001/index.html"},{"id":"MEJE-KW-007002","row_version":1,"title":"병약한 미인 인물상","original":"Delicate and Sickly","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"병을 앓는 인물을 가냘프고 사랑스러운 외모로 그리며 고통의 흔적은 제한적으로만 보여 주는 관습이다. 질병과 아름다움을 결합하는 재현이 현실을 단순화할 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007002/index.html"},{"id":"MEJE-KW-007003","row_version":2,"title":"맛있는 음식의 공상","original":"Delicious Daydream","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"배고픈 인물이 먹고 싶은 음식을 상상하며 맛과 향을 떠올린다. 실제 식사보다 기대와 욕망을 먼저 보여 준다. 음식을 머릿속에 그리는 욕망이 실제 장면에서 행동을 흐트러뜨리면 먹을거리로 빼앗긴 주의이 된다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-007003/index.html"},{"id":"MEJE-KW-007004","row_version":1,"title":"먹을거리로 빼앗긴 주의","original":"Delicious Distraction","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 맛있어 보이는 음식에 정신을 빼앗겨 하던 일이나 주변의 위험을 놓친다. 식욕이 행동의 방향을 바꾸는 순간이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007004/index.html"},{"id":"MEJE-KW-007005","row_version":1,"title":"친근하고 다정한 용","original":"Delightful Dragon","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"위협적인 괴물로 기대한 용이 사람과 우정을 나누고 온화한 성격을 보인다. 거대한 힘과 친밀한 관계가 함께 그려진다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-007005/index.html"},{"id":"MEJE-KW-007006","row_version":1,"title":"수수께끼를 즐기는 인물","original":"Delighting in Riddles","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 꼭 숨길 필요가 없는 말도 수수께끼처럼 돌려 표현하며 다른 사람의 추리를 즐긴다. 정보 전달보다 놀이가 말투의 목적이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007006/index.html"},{"id":"MEJE-KW-007007","row_version":2,"title":"불량아의 머리 모양","original":"Delinquent Hair","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"눈에 띄는 머리 모양이나 색을 반항적인 인물의 시각적 신호로 사용하는 관습이다. 실제 사람의 성격을 외형만으로 판단하는 근거는 아니다. 외형으로 인물 유형을 암시하는 예로 불량 청소년과 연결된다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-007007/index.html"},{"id":"MEJE-KW-007008","row_version":1,"title":"불량 청소년","original":"Delinquents","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"사회 규범이나 학교의 질서에 반항하며 작은 범법 행위에 얽히는 젊은 인물 유형이다. 악인으로만 고정되지 않고 소속감과 성장의 문제를 담을 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007008/index.html"},{"id":"MEJE-KW-007009","row_version":2,"title":"혼란 속의 사람 착각","original":"Delirious Misidentification","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"병이나 혼란으로 판단이 흐려진 인물이 눈앞의 사람을 가까운 이나 적으로 잘못 알아본다. 잘못된 인식이 위로 또는 새로운 위험을 만든다. 자신이나 타인의 정체성을 잘못 인식한다는 점에서 자신을 동물이라 믿는 인물과 비교할 수 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-007009/index.html"},{"id":"MEJE-KW-007010","row_version":1,"title":"지옥에서 구원받는 영혼","original":"Deliverance from Damnation","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"죄를 지었거나 악역이었던 인물이 죽어 벌을 받다가 다른 이의 도움이나 자신의 변화로 구원의 가능성을 얻는다. 생전의 잘못과 사후의 회복을 함께 묻는다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-007010/index.html"},{"id":"MEJE-KW-007011","row_version":2,"title":"아이가 생겨 악행을 버리는 인물","original":"Deliver Us from Evil","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"악행을 해 오던 여성이 임신을 계기로 아이를 위해 이전 삶을 떠나려 한다. 부모가 되리라는 자각을 갑작스러운 도덕적 전환의 계기로 삼는 관습이다. 부모와 자녀 사이의 사랑을 어떻게 이해하는가는 부모의 사랑을 오해하는 자녀과 다른 방향의 갈등을 만든다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-007011/index.html"},{"id":"MEJE-KW-007012","row_version":2,"title":"출산을 돕는 비전문가 남성","original":"Delivery Guy","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"전문 의료진이 없는 자리에서 남성 인물이 출산 중인 사람의 곁을 지키고 도움을 주는 역할을 맡는다. 작품은 당황스러운 희극이나 관계의 전환점으로 그리곤 한다. 출산을 앞둔 상황이 주변 인물의 역할을 바꾼다는 점에서 아이가 생겨 악행을 버리는 인물과 이어진다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007012/index.html"},{"id":"MEJE-KW-007013","row_version":1,"title":"배달원을 가장한 잠입","original":"Delivery Guy Infiltration","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"인물이 배달원인 척하며 경계받지 않고 문턱이나 출입구를 넘으려 한다. 일상적인 방문자에 대한 기대를 위장 장치로 이용하는 전개다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-007013/index.html"},{"id":"MEJE-KW-007014","row_version":1,"title":"보내지 않을 편지","original":"Delivery Not Desired","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 받을 사람을 떠올리며 편지나 메시지를 쓰지만 실제로 전할 생각은 없다. 전해지지 않은 말이 내면의 감정을 드러낸다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007014/index.html"},{"id":"MEJE-KW-007015","row_version":1,"title":"아기를 데려오는 황새","original":"Delivery Stork","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"아기가 어디서 오는지 묻는 아이에게 황새가 데려다준다는 이야기로 답하는 전승이다. 작품에서는 출생을 우회해 설명하는 익숙한 상징으로 쓰인다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-007015/index.html"}]}.cards;